/// <summary>
/// VendInvoiceEventHandler class extension for vendor pending invoice workflow
/// </summary>
[ExtensionOf(classStr(VendInvoiceEventHandler))]
final class METVendInvoiceEventHandler_Extension
{
    
}

Method.Source:
    /// <summary>
    /// Coc to start custom invoice matching process
    /// </summary>
    /// <param name="_workflowEventArgs">
    /// An instance of the <c>WorkflowEventArgs</c> class.
    /// </param>
    public void started(WorkflowEventArgs _workflowEventArgs)
    {
        boolean                 metValid;
        str                     metMessage;
        VendInvoiceInfoTable    metsavedVendInvoiceInfoTable = VendInvoiceInfoTable::findRecId(_workflowEventArgs.parmWorkflowContext().parmRecId());
        METVendParameters       vendParm = METVendParameters::find();
        METVendInvoiceMatching  metinvoiceMatching = METVendInvoiceMatching::construct();
        
        try
        {
            // CB748_PricingConditions - Running before the claim line is created to ensure the offremittance charges and taxes are updated
            // Charges need to be applied only after the custom task within the invoice workflow creates a service item line
            // in the pending vendor invoice lines for invoice match variance is completed
            METPendingVendorInvoiceOffRemittanceRebate offRemittanceRebate = METPendingVendorInvoiceOffRemittanceRebate::construct(metsavedVendInvoiceInfoTable);
            //offRemittanceRebate.run();

            if (METVendParameters::find().EnableMetcashMatchingLogic && !metsavedVendInvoiceInfoTable.skipCustomInvoiceMatching() && !metsavedVendInvoiceInfoTable.isLandedCostEnabled())
            {
                [metValid, metMessage] = VendInvoiceHeaderWorkflow::metValidateSubmissionForInvoiceMatching(metsavedVendInvoiceInfoTable);

                if(!metValid)
                {
                    throw error(metMessage);
                }

                if (metsavedVendInvoiceInfoTable.RecId && !metsavedVendInvoiceInfoTable.isNonPO() && !metsavedVendInvoiceInfoTable.METClaimInvoice && !metsavedVendInvoiceInfoTable.skipCustomInvoiceMatching())
                {
                    metinvoiceMatching.parmVendInvoiceInfoTable(metsavedVendInvoiceInfoTable);
                    metinvoiceMatching.generateFailureMatchingLines();
                }
            }

            next started(_workflowEventArgs);

            // CB748_PricingConditions
            // Charges need to be applied only after the custom task within the invoice workflow creates a service item line
            // in the pending vendor invoice lines for invoice match variance is completed
            offRemittanceRebate.run();

        }
        catch
        {
            error("@ApplicationCommon:WorkflowHistoryWorkflowFailureTimelineEntryHeader");
        }
    }

    /// <summary>
    /// Coc for completion of custom invoice matching process
    /// </summary>
    /// <param name="_workflowEventArgs">
    /// An instance of the <c>WorkflowEventArgs</c> class.
    /// </param>
    public void completed(WorkflowEventArgs _workflowEventArgs)
    {
        if (METVendParameters::find().EnableMetcashMatchingLogic)
        {
            VendInvoiceInfoTable metVendorInvoice = VendInvoiceInfoTable::findRecId(_workflowEventArgs.parmWorkflowContext().parmRecId());

            if (!metVendorInvoice.skipCustomInvoiceMatching() && !metVendorInvoice.isLandedCostEnabled())
            {
                METVendInvoiceMatching  metInvoiceMatching = METVendInvoiceMatching::construct();

                if (metVendorInvoice.RecId != 0 && !metVendorInvoice.METClaimInvoice && metVendorInvoice.displayMETHasClaimLines() && !metVendorInvoice.displayMETVarInTolerance())
                {
                    metInvoiceMatching.parmVendInvoiceInfoTable(metVendorInvoice);
                    VendInvoiceInfoTable claimInvoice = metInvoiceMatching.createClaimInvoice();

                    // CB748_PricingConditions
                    METPendingVendorInvoiceOffRemittanceRebate offRemittanceRebate = METPendingVendorInvoiceOffRemittanceRebate::construct(claimInvoice);
                    offRemittanceRebate.run();
                }
            }
        }

        next completed(_workflowEventArgs);
    }
